        dedupe: "Slow and fast pointers: W marks the end of the part kept so far, R reads ahead. A value is kept only when it differs from the last one kept. Every value is read once and written at most once: O(n) time, no extra space.",
        partition: "Everything left of L is smaller than the pivot, from L to M − 1 equal, and right of H larger; from M to H is still unknown. Each step looks at a[M] and shrinks the unknown part by one: one pass, O(n), in place. Quicksort uses it when values repeat.",
        cycle: "Each value is the index of the next cell, so following them from index 0 must end in a loop. T moves one cell a step and H two, so inside the loop H gains a cell a step and catches T. Then S from the start and H from the meeting point, one cell each, meet at the loop's entrance. O(n) time and O(1) space — the way to find the repeated number among n + 1 values from 1 to n.",
